input.proposed_solution:
Add csvField(): a field is wrapped in double quotes when it contains a comma, a double quote, CR or LF, and embedded double quotes are doubled, as RFC 4180 specifies. Plain fields are emitted unchanged. Added a test with commas, quotes and an embedded newline.

Patch (already applied in the repository snapshot):
```diff
--- a/src/csv.js
+++ b/src/csv.js
@@ -1,9 +1,18 @@
 // @ts-check
+
+/**
+ * RFC 4180 field: quote when it contains a comma, double quote, CR or LF; double embedded quotes.
+ * @param {string | number | null} value
+ */
+export function csvField(value) {
+  const s = String(value ?? "");
+  return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
+}

 /**
  * @param {string[]} header
  * @param {Array<Array<string | number | null>>} rows
  */
 export function toCsv(header, rows) {
-  return [header, ...rows].map((r) => r.map((v) => String(v ?? "")).join(",")).join("\r\n");
+  return [header, ...rows].map((r) => r.map(csvField).join(",")).join("\r\n");
 }
--- a/test/csv.test.js
+++ b/test/csv.test.js
@@ -5,3 +5,7 @@
 test("simple rows", () => {
   assert.equal(toCsv(["a", "b"], [[1, "x"], [2, null]]), "a,b\r\n1,x\r\n2,");
 });
+
+test("quotes commas, quotes and newlines", () => {
+  assert.equal(toCsv(["note"], [["a,b"], ['say "hi"'], ["line1\nline2"]]), 'note\r\n"a,b"\r\n"say ""hi"""\r\n"line1\nline2"');
+});
```
